package net.zartra.gui;
import static org.junit.Assert.*;import org.bukkit.Material;import org.bukkit.inventory.ItemStack;import org.junit.Test;
public class EditorMovementAndLeatherControlTest {@Test public void everyLeatherArmorCapabilityIsVisible(){assertTrue(LeatherColorCompat.capable(new MenuItem(new ItemStack(Material.LEATHER_HELMET),null)));assertTrue(LeatherColorCompat.capable(new MenuItem(new ItemStack(Material.LEATHER_CHESTPLATE),null)));assertTrue(LeatherColorCompat.capable(new MenuItem(new ItemStack(Material.LEATHER_LEGGINGS),null)));assertTrue(LeatherColorCompat.capable(new MenuItem(new ItemStack(Material.LEATHER_BOOTS),null)));assertFalse(LeatherColorCompat.capable(new MenuItem(new ItemStack(Material.STONE),null)));}@Test public void productionMovementHandlesBothShiftDirections()throws Exception{String s=new String(java.nio.file.Files.readAllBytes(java.nio.file.Paths.get("src/main/java/net/zartra/gui/GuiService.java")),"UTF-8");assertTrue(s.contains("shiftLowerToEditor"));assertTrue(s.contains("addLiveLower(p,move)"));assertTrue(s.contains("if(e.isShiftClick()){shiftLowerToEditor"));assertTrue(s.contains("if(e.isRightClick()&&slot!=null)"));}}